import base64
import json

# 完整 JWT
token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..M8HW4Nkl0XPlBHT20oVfobRZfvMMd1LRFxFHp51XGqQ"

def b64decode(s):
    return base64.urlsafe_b64decode(s + '=' * (-len(s) % 4))

parts = token.split('.')
print("=== JWT Structure ===")
print(f"Header ({len(parts[0])} chars):")
print(json.dumps(json.loads(b64decode(parts[0])), indent=2))
print(f"\nPayload ({len(parts[1])} chars):")
payload = json.loads(b64decode(parts[1]))
print(json.dumps(payload, indent=2, ensure_ascii=False))
print(f"\nSignature ({len(parts[2])} chars): {parts[2][:50]}...")

# refreshToken
refresh_token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpZCI6MSwiaWF0IjoxNzg4MDU1MDY1fQ.IxQ7S_h81fbssOYqhcl8A6_V_krXCkQQYSZkecm3M5s"
rparts = refresh_token.split('.')
print(f"\n=== refreshToken ===")
print(f"Payload: {json.loads(b64decode(rparts[1]))}")
print(f"Signature: {rparts[2]}")

# iat → 时间
import datetime
iat = payload.get('iat')
exp = payload.get('exp')
print(f"\n=== 时间 ===")
print(f"iat={iat} → {datetime.datetime.utcfromtimestamp(iat).isoformat()} UTC")
print(f"exp={exp} → {datetime.datetime.utcfromtimestamp(exp).isoformat()} UTC")
print(f"有效期 = {(exp-iat)/86400:.1f} 天 = {(exp-iat)/3600:.1f} 小时")

# Permissions 统计
perms = payload.get('permissions', [])
print(f"\n=== 权限位 (n={len(perms)}) ===")
for p in perms:
    print(f"  {p}")
